export const concepts = [
  ['JAVA-R2-CON001', 'source, compiler, and JVM', 'Java source is checked and compiled before the JVM runs the resulting class instructions.', '`javac Main.java` reports compile errors before `java Main` can run.', 'Treating an old successful run as proof that the edited source compiled.'],
  ['JAVA-R2-CON002', 'class and main', 'A beginner console application starts in a class method named main with the required signature.', '`public static void main(String[] args)` is the entry point.', 'Changing the method name or omitting static and expecting the launcher to find it.'],
  ['JAVA-R2-CON003', 'diagnostic evidence', 'A compiler error or stack trace names a location, type, and message that narrows the repair.', 'A missing semicolon is reported at or near the affected statement.', 'Changing multiple unrelated lines before reading the first useful diagnostic.'],
  ['JAVA-R2-CON004', 'declared type', 'Every Java variable has a declared type that constrains values and operations.', '`int minutes = 95;` stores a whole number.', 'Putting quoted numeric text into an int without conversion.'],
  ['JAVA-R2-CON005', 'String value comparison', 'String.equals compares text content; == compares whether references identify the same object.', '`answer.equals("yes")` checks content.', 'Using == for user-entered text.'],
  ['JAVA-R2-CON006', 'Scanner boundary', 'Scanner reads console input, and mixing token and line methods requires deliberate newline handling.', '`scanner.nextLine()` reads the remaining line.', 'Calling nextInt then nextLine without accounting for the pending line ending.'],
  ['JAVA-R2-CON007', 'numeric parsing', 'Parsing converts valid numeric text and throws a specific exception for invalid text.', '`Integer.parseInt(ageText)` produces an int.', 'Catching every Exception around the whole program.'],
  ['JAVA-R2-CON008', 'ordered branch', 'An if/else-if/else chain chooses the first matching branch.', 'Reject invalid ages before testing eligibility.', 'Putting a broad success condition before a required rejection.'],
  ['JAVA-R2-CON009', 'short-circuit Boolean logic', '&& and || evaluate left to right and may skip the right operand once the result is known.', '`age >= 16 && hasId` requires both.', 'Using | or & without understanding eager evaluation.'],
  ['JAVA-R2-CON010', 'loop progress', 'A while loop needs an update that can move its condition toward false.', 'Increment acceptedCount only after a valid record.', 'Incrementing the wrong counter and never reaching the stop rule.'],
  ['JAVA-R2-CON011', 'array boundary', 'An array has fixed length and indexes from zero through length minus one.', '`scores[scores.length - 1]` is the last score.', 'Reading scores[scores.length].'],
  ['JAVA-R2-CON012', 'enhanced for loop', 'An enhanced for loop visits each value when the index itself is unnecessary.', '`for (int score : scores)` traverses all scores.', 'Trying to resize the array through the loop variable.'],
  ['JAVA-R2-CON013', 'typed ArrayList', 'An ArrayList stores a growable ordered collection of one declared element type.', '`ArrayList<String> names = new ArrayList<>();`.', 'Mixing unrelated value types or using size as the last index.'],
  ['JAVA-R2-CON014', 'method contract', 'A method contract states parameter types, return type, and one responsibility.', '`static double subtotal(List<Double> prices)` returns a number.', 'Collecting input, calculating, saving, and printing in one method.'],
  ['JAVA-R2-CON015', 'return value', 'return sends a compatible value to the caller and ends that invocation.', '`return subtotal - discount;` can be composed.', 'Printing when the caller needs the value.'],
  ['JAVA-R2-CON016', 'local scope', 'A local variable exists only inside its declaring block.', 'A subtotal inside calculateTotal is not visible in main.', 'Relying on hidden mutable fields instead of parameters and returns.'],
  ['JAVA-R2-CON017', 'method overload', 'Overloads share a name but differ by parameter list, not only return type.', '`format(int)` and `format(double)` can coexist.', 'Changing only the return type and expecting a valid overload.'],
  ['JAVA-R2-CON018', 'constructor and instance', 'A constructor establishes one new object’s initial field values.', '`new Book("Kindred")` creates an independent Book.', 'Using shared static state for per-book availability.'],
  ['JAVA-R2-CON019', 'private field and public behavior', 'Private fields protect state while public methods provide controlled operations.', '`checkout()` validates before changing available.', 'Making every field public and allowing invalid transitions.'],
  ['JAVA-R2-CON020', 'this', 'this names the receiving object and distinguishes its fields from parameters.', '`this.title = title;` assigns the field.', 'Assigning `title = title` and leaving the field unchanged.'],
  ['JAVA-R2-CON021', 'object collection', 'A typed list can hold objects and call their public methods while traversing.', '`ArrayList<Book>` stores Book instances.', 'Duplicating object fields in unrelated parallel arrays.'],
  ['JAVA-R2-CON022', 'Path and Files', 'Path identifies a location; Files performs explicit text I/O at that location.', '`Files.readAllLines(path, UTF_8)` reads stored records.', 'Assuming the working directory without recording it.'],
  ['JAVA-R2-CON023', 'missing versus malformed data', 'A missing first-run file differs from an existing line that cannot be parsed.', 'No file may start empty; a malformed line must stop without overwrite.', 'Treating every load failure as an empty first run.'],
  ['JAVA-R2-CON024', 'narrow catch', 'A catch should handle only an expected failure at the smallest useful boundary.', 'Catch NumberFormatException around integer parsing.', 'Catching Exception and continuing with corrupt state.'],
  ['JAVA-R2-CON025', 'breakpoint evidence', 'A breakpoint pauses before a suspicious statement so values and control flow can be inspected.', 'Pause before a counter update and inspect index and total.', 'Adding random edits before reproducing one stable case.'],
  ['JAVA-R2-CON026', 'check harness', 'A small check compares actual and expected behavior and fails visibly on mismatch.', '`checkEquals("first id", 1, actualId)` records intent.', 'Changing the expected value just to make a check pass.'],
  ['JAVA-R2-CON027', 'command-line argument contract', 'The args array contains tokens supplied after the class name and must be validated before use.', '`java Main add "Finish lab"` produces three argument tokens as defined.', 'Reading args[0] before checking the length.'],
  ['JAVA-R2-CON028', 'reproducible repository', 'A repository is reviewable when tracked files and README let another learner compile, run, and verify it safely.', 'README gives exact JDK, IntelliJ, javac/java, and check commands.', 'Publishing IDE caches, credentials, private records, or undocumented commands.'],
].map(([id, term, simpleMeaning, example, commonMistake]) => ({ id, term, simpleMeaning, example, commonMistake }));

const build = ({ week, title, outcome, brief, competencyIds, priorKnowledgeCompetencyIds, conceptRefs, whyItMatters, steps, criteria, hints, templates, stretch, sessions, finishedResult }) => {
  const prefix = `JAVA-R2-B-W${String(week).padStart(2, '0')}-01`;
  return {
    id: prefix, title, required: true, outcome, competencyIds,
    estimatedMinutes: sessions.reduce((sum, session) => sum + session.minutes, 0), brief,
    steps: steps.map((text, index) => ({ id: `${prefix}-S${String(index + 1).padStart(2, '0')}`, text })),
    acceptanceCriteria: criteria.map((text, index) => ({ id: `${prefix}-A${String(index + 1).padStart(2, '0')}`, text })),
    hints,
    templates: templates.map((item, index) => ({ id: `${prefix}-T${String(index + 1).padStart(2, '0')}`, ...item })),
    stretch,
    learnerGuide: {
      summary: brief, whyItMatters, priorKnowledgeCompetencyIds, finishedResult, conceptRefs,
      sessions: sessions.map((session, index) => ({ id: `${prefix}-SESSION-${String(index + 1).padStart(2, '0')}`, title: session.title, estimatedMinutes: session.minutes, stepIds: session.stepIndexes.map((stepIndex) => `${prefix}-S${String(stepIndex).padStart(2, '0')}`) })),
    },
  };
};

